Algorithme TriSelection;
Var
    T[100] : Entier;
    N, i, j, minIdx, Temp : Entier;
Debut
    N := 5;
    T[1] := 42; T[2] := 12; T[3] := 89; T[4] := 7; T[5] := 23;

    // Algorithme du Tri par Sélection
    Pour i := 1 a N - 1 Faire
        minIdx := i;
        Pour j := i + 1 a N Faire
            Si (T[j] < T[minIdx]) Alors
                minIdx := j;
            Fin Si;
        Fin Pour;

        // Permutation (Swap) avec le plus petit élément trouvé
        Si (minIdx <> i) Alors
            Temp := T[i];
            T[i] := T[minIdx];
            T[minIdx] := Temp;
        Fin Si;
    Fin Pour;

    // Affichage du tableau trié
    Pour i := 1 a N Faire Ecrire(T[i]); Fin Pour;
Fin.

Algorithme ParcoursMatrice;
Var
    M[1..10, 1..10] : Entier;
    L, C, i, j, Somme : Entier;
Debut
    L := 3; C := 3;

    // Saisie d'une matrice 3x3 par deux boucles imbriquées
    Pour i := 1 a L Faire
        Pour j := 1 a C Faire
            Ecrire("M[", i, ",", j, "] :");
            Lire(M[i, j]);
        Fin Pour;
    Fin Pour;

    // Calcul de la somme des éléments de la Diagonale Principale (i = j)
    Somme := 0;
    Pour i := 1 a L Faire
        Somme := Somme + M[i, i];
    Fin Pour;
    Ecrire("Somme de la diagonale principale = ", Somme);
Fin.
